import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val) public {
        // 1. Keep the domain wide; only avoid overflow in MinSum if needed (it's a uint, any value is fine).
        // No vm.assume needed; _val is any uint256.

        // 2. Set up the scenario where the second call to SetMinSum should revert because initialized is true.
        // First, we need to initialize the contract.
        c.Initialized();
        // Record MinSum before the second call.
        uint256 minSumBefore = c.MinSum();

        // 3. Call SetMinSum again; it should revert because initialized is true.
        bool ok;
        try c.SetMinSum(_val) {
            ok = true;
        } catch {
            ok = false;
        }

        // 4. Assert the property: if it reverted (ok == false), MinSum must be unchanged.
        // If it somehow succeeded (ok == true), MinSum must equal _val. (This branch covers the edge case where the first call also reverted, but here we know it reverts).
        // The reference satisfies: !ok => c.MinSum() == minSumBefore.
        // The bug fails: it sets MinSum before revert, so c.MinSum() == _val even though ok == false.
        assertTrue(ok || c.MinSum() == minSumBefore);
    }
}

