pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initial, uint256 deposit, uint16 lockTime) public {
        // Keep values in a wide admissible domain that avoids overflow and the unlock-time extension path
        vm.assume(initial <= type(uint112).max);
        vm.assume(deposit <= type(uint112).max);
        vm.assume(initial + deposit <= type(uint112).max);

        // Ensure msg.sender (this contract) has some initial state by doing a Put with a fixed timestamp
        address me = address(this);
        vm.deal(me, initial + deposit);
        if (initial > 0) {
            vm.warp(1000);
            c.Put{value: initial}(0);
        }

        // Set block.timestamp to a value such that adding lockTime does NOT extend unlockTime
        uint256 currTime = block.timestamp;
        uint256 curUnlock = c.Acc(me).unlockTime;
        // To avoid extending unlockTime, we need block.timestamp + lockTime <= curUnlock
        // We can use a small lockTime and set block.timestamp far in the past relative to curUnlock
        // But curUnlock is block.timestamp of the previous Put; to guarantee no extension,
        // we just use a lockTime of 0 or ensure timestamp is sufficiently low.
        // Instead we simply warp back to a time where adding lockTime does not exceed curUnlock.
        // Since curUnlock may be 1000 from earlier Put, we set timestamp to 0 and lockTime small.
        // But warp can only move forward. Alternative: we rely on the fact that with lockTime == 0,
        // block.timestamp+0 is always <= curUnlock if block.timestamp <= curUnlock, which is true when we warp to a time <= curUnlock.
        // We'll just set lockTime to 0 by bounding it, and adjust warp accordingly.
        // However the parameter is lockTime (uint16). We can bound it to 0 to disable extension.
        vm.assume(lockTime == 0);
        // Also ensure no overflow in timestamp addition
        vm.warp(currTime); // stay at current time, which is <= curUnlock

        uint256 balanceBefore = c.Acc(me).balance;
        uint256 ethBefore = address(c).balance;

        c.Put{value: deposit}(lockTime);

        uint256 balanceAfter = c.Acc(me).balance;
        uint256 ethAfter = address(c).balance;

        // General invariant: balance increment equals exactly msg.value (no extra wei)
        // The reference always satisfies balanceAfter == balanceBefore + deposit.
        // The mutant adds +1, so this equality fails.
        assertTrue(balanceAfter == balanceBefore + deposit);
    }
}

