        // Record unlock time after second Put
        (, uint256 unlockAfter) = c.Acc(actor);

        // The invariant: unlock time must never decrease after a Put.
        // The reference always satisfies unlockAfter >= unlockBefore.
        // The mutant never updates unlockTime, so if the second Put would extend it,
        // unlockAfter remains equal to unlockBefore instead of growing.
        assertTrue(unlockAfter >= unlockBefore);
