        c.Put{value: amt}(lock2);
        uint expectedUnlock = (start + lock1 > start + warpAfterFirst + lock2) ? start + lock1 : start + warpAfterFirst + lock2;
        uint actualUnlock = c.Acc(address(this)).unlockTime;
        assertTrue(actualUnlock == expectedUnlock);
    }
}
